1759: /**
1760:  * The imported DLLs that Windows could not resolve, so LoadLibrary of this
1761:  * image fails with ERROR_MOD_NOT_FOUND. A dependency is satisfied when its
1762:  * file exists, or when it is a DLL the emulator answers for -- recognised by
1763:  * at least one of the names imported from it being a known API. An
1764:  * ordinal-only dependency cannot be checked by name and is assumed present.
1765:  * Monster Truck Madness 2 probes Trirend.dll, whose redline.dll (the Rendition
1766:  * Verite runtime) is not installed; Windows refuses that load and the game
1767:  * drops the renderer, where binding fail-fast stubs crashed on VL_OpenVerite.
1768:  * @param {Uint8Array} bytes
1769:  * @param {(name: string) => boolean} apiKnown
1770:  * @param {(dll: string) => boolean|Promise<boolean>} dllExists
1771:  * @returns {Promise<string[]>} lowercase DLL names
1772:  */
1773: async function missingImportDependencies(bytes, apiKnown, dllExists) {
1774:   const missing = [];
1775:   for (const dep of importsByDll(bytes)) {
1776:     if (!dep.names.length) continue;
1777:     if (isWindowsSystemDll(dep.dll)) continue;
1778:     if (dep.names.some(n => apiKnown(n))) continue;
1779:     if (await dllExists(dep.dll)) continue;
1780:     missing.push(dep.dll);
1781:   }
1782:   return missing;
1783: }
